///////// 2. 초기화 영역 /////////
scwin.onpageload = async function () {
    try {
        scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL52100.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 *  파일업로드 후 저장 처리
 */
scwin.muc_onprogress = async function (data) {
};

scwin.muc_ondone = async function (data) {
    try {
        if (scwin.searchType === "0") {
            await $c.win.alert($c.data.getMessage("com_complete_0150", "저장"));
        } else {
            await $c.win.alert($c.data.getMessage("com_complete_0150", "수정"));
        }

        $c.win.moveUrl("/ui/lst/lstinvstg/ULDFIL52000.xml");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL52100.muc_ondone" });
    }
};

scwin.muc_oncomplete = function () {
};

scwin.muc_onerror = function (data) {
};

