/* 
 * 목록 버튼
 */
scwin.btn_goList_onclick = function (e) {
    try {
        // $c.win.closePopup();
        $c.win.moveUrl("/ui/lst/lstinvstg/ULDFIL52000.xml");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52100.btn_goList_onclick" });
    }
};

/* 
 * 회사명 검색 버튼 - 예비심사 접수 법인 목록 팝업창
 */
scwin.btn_findAcptCompany_onclick = async function (e) {
    try {
        const data = {
            isurCd: $c.session.getUserInfo("isurCd"),
        };
        const opts = {
            id: "ULDFIL52110",
            popupName: "법인명 찾기",
            width: 900,
            height: 500,
            frameModal: "top",
            type: "pageFramePopup",
        };
        let res = await $c.win.openPopup("/ui/lst/lstinvstg/ULDFIL52110.xml", opts, data);
        if (res) {
            scwin.setCorpInfo(res.isurCd, res.comNm, res.bzProcsNo);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL52100.btn_findAcptCompany_onclick" });
    }
};

/* 
 * 의무보유내역 선택 버튼
 */
scwin.btn_findPrtDepo_onclick = async function (e) {
    try {
        if (scwin.bzProcsNo === undefined || scwin.bzProcsNo === null || scwin.bzProcsNo === "") {
            await $c.win.alert($c.data.getMessage("com_crud_0199", "회사명"));
            return
        }
        const data = {
            isurCd: ibx_isurCd.getValue(), // 발행회사코드
            bzProcsNo: scwin.bzProcsNo, // 업무처리번호
        };
        const opts = {
            id: "ULDFIL52120",
            popupName: "의무보유내역",
            width: 900,
            height: 500,
            frameModal: "top",
            type: "pageFramePopup",
        };
        let res = await $c.win.openPopup("/ui/lst/lstinvstg/ULDFIL52120.xml", opts, data);
        if (res) {
            scwin.setPrtDepoInfo(res.nm, res.id, res.shrs, res.objKind);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL52100.btn_findPrtDepo_onclick" });
    }
};

/* 
 * 저장 버튼
 */
scwin.btn_save_onclick = function (e) {
    try {
        if (scwin.searchType === "0") {
            scwin.insertPrtDepoWithd();
        } else if (scwin.searchType === "2") {
            scwin.updatePrtDepoWithd("2");
        } else if (scwin.searchType === "3") {
            scwin.updatePrtDepoWithd("3");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52100.btn_save_onclick" });
    }
};

/* 
 * 수정 버튼
 */
scwin.btn_update_onclick = function (e) {
    try {
        if (scwin.searchType === "0") {
            scwin.insertPrtDepoWithd();
        } else if (scwin.searchType === "2") {
            scwin.updatePrtDepoWithd("2");
        } else if (scwin.searchType === "3") {
            scwin.updatePrtDepoWithd("3");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52100.btn_update_onclick" });
    }
};

/* 
 * 처분신청 공문 파일 업로드
 */
scwin.upd_singleFileUpload_onInputValueChange = function (fileName) {
    try {
        dma_saveReq.set("files", fileName); // files
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52100.upd_singleFileUpload_onInputValueChange" });
    }
};

/**
 *  파일추가 버튼 클릭시 파일선택 화면 호출
 */
scwin.mUpBtn_onclick = function (e) {
    try {
        $c.util.onUploadClick(muc);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52100.mUpBtn_onclick" });
    }
};

scwin.btn_upload1_onclick = function (e) {
    try {
        scwin.btnGubun = 0;
        $c.util.onUploadClick(muc);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52100.btn_upload1_onclick" });
    }
};

scwin.btn_upload2_onclick = function (e) {
    try {
        scwin.btnGubun = 1;
        $c.util.onUploadClick(muc);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52100.btn_upload2_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/* 
 * 상세조회
 */
scwin.search = async function () {
    dma_selectOneReq.set("prtDepoNo", scwin.prtDepoNo); // 업무처리번호
    dma_selectOneReq.set("searchType", scwin.searchType); // 0:최초입력, 1:해당기업조회, 2:입력후저장내용 불러오기, 3:수정, 4:첨부파일, 5:최종승인 , 6:최종승인 반려
    const sbmOptions = {
        id: "sbm_selectOne",
        method: "get",
        action: "/api/listing/listinvstg/prtdepo-disposal/select-one",
        ref: "dma_selectOneReq",
        target: "dma_selectOneRes=body, dlt_selectOneRes_prtDepoAttachFiles=body.prtDepoAttachFiles",
        // gridview : "grd_list",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_selectOne_submitdone(sbmRtn);
}

/* 
 * 상세조회 완료
 */
scwin.sbm_selectOne_submitdone = function (e) {

    // 화면 데이터
    ibx_comNm.setValue(dma_selectOneRes.get("comNm")); // 회사명
    ibx_isurCd.setValue(dma_selectOneRes.get("isurCd")); // 회사코드
    ibx_shrhdNm.setValue(dma_selectOneRes.get("shrhdNm")); // 의무보유자명
    // ibx_fstPrtDepoShrs.setValue(dma_selectOneRes.get("fstPrtdepoShrs").replace(",", "")); //최초의무보유 주식수
    // ibx_prtDepoWithdShrs.setValue(dma_selectOneRes.get("prtdepoWithdShrs").replace(",", "")); //처분 주식수
    ibx_fstPrtDepoShrs.setValue(scwin.toNumber(dma_selectOneRes.get("fstPrtdepoShrs"))); // 최초의무보유 주식수
    ibx_prtDepoWithdShrs.setValue(scwin.toNumber(dma_selectOneRes.get("prtdepoWithdShrs"))); // 처분 주식수

    ibx_objKind.setValue(); // 의무보유대상종류
    ibx_prtdepoWithdRsn.setValue(dma_selectOneRes.get("prtdepoWithdRsn")); // 처분 사유
    if (dma_selectOneRes.get("prtdepoReopnYn") === "Y") { // 재의무보유 여부(체크박스)
        cbx_prtDepoReopnYn.setSelectedIndex(0); // 체크박스 클릭
    }
    cal_prtDepoReopnDD.setValue(dma_selectOneRes.get("prtdepoReopnDd")); // 재의무보유 여부(날짜)
    // ibx_lstPrtDepoShrs.setValue(dma_selectOneRes.get("lstPrtdepoShrs").replace(",", "")); //최종의무보유 주식수
    ibx_lstPrtDepoShrs.setValue(scwin.toNumber(dma_selectOneRes.get("lstPrtdepoShrs"))); // 최종의무보유 주식수

    // upload1; //처분신청 공문
    // upload2; //첨부서류

    // 화면 외 수정 데이터
    scwin.bzProcsNo = dma_selectOneRes.get("bzProcsNo");
    scwin.prtDepoId = dma_selectOneRes.get("prtdepoId");
    scwin.prtDepoNo = dma_selectOneRes.get("prtdepoNo");
    dma_saveReq.set("prtdepoWithdApplSeq", dma_selectOneRes.get("prtdepoWithdApplSeq"));

    // 파일정보 세팅
    for (let i = 0; i < dlt_selectOneRes_prtDepoAttachFiles.getRowCount(); i++) {
        let prtdepoWithdAttachTpCd = dlt_selectOneRes_prtDepoAttachFiles.getCellData(i, "prtdepoWithdAttachTpCd");
        let attachFileNm = dlt_selectOneRes_prtDepoAttachFiles.getCellData(i, "attachFileNm");
        if (prtdepoWithdAttachTpCd === "1") {
            ibx_upload1.setValue(attachFileNm);
        } else if (prtdepoWithdAttachTpCd === "2") {
            ibx_upload2.setValue(attachFileNm);
        }
    }
}

// 파일업로드시 파일정보 dataList에 세팅
scwin.selectCallback = function (fileInfoArr) {
    const fileInfos = muc.getFileInfos();
    if (scwin.btnGubun === 0) {
        ibx_upload1.setValue(fileInfos[0].name);
    } else {
        ibx_upload2.setValue(fileInfos[1].name);
    }
}

///////// 5. 일반/업무 함수 영역 /////////
/* 
 * 화면 초기화
 */
scwin.init = async function () {
    const getParam = $c.data.getParameter();
    scwin.prtDepoNo = getParam.prtDepoNo;
    scwin.searchType = getParam.searchType;

    // let uploadCode = '${uploadCode}';
    // let prtDepoNo = '${prtDepoNo}';
    // let searchType = '${searchType}';
    // if(searchType != '' && searchType != '0'){
    // 	if(uploadCode == '0'){
    // 		$c.win.alert('저장되었습니다.');
    // 	}else if(uploadCode == '1'){
    // 		$c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
    // 	}else if(uploadCode == '2'){
    // 		$c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
    // 	}else{
    // 		if(prtDepoNo == ''){
    // 			$c.win.alert('저장시 오류가 발생하였습니다.');
    // 		}
    // 	}  	
    // }

    let userInfo = $c.session.getUserInfo();
    tbx_userInfo.setValue(userInfo.integUsrId + "/" + userInfo.corpUsrNm);

    if (!$c.util.isEmpty(scwin.searchType) && scwin.searchType !== "0") {
        btn_save.hide();
        btn_update.show();
        await scwin.search();
    } else {
        btn_save.show();
        btn_update.hide();
    }

    // 컴포넌트 객체 전달
    $c.date.checkCalendarFormat("cal_prtDepoReopnDD", "yyyyMMdd");
}

// 파일다운로드 
scwin.fileDown = function (prtDepoId, prtDepoIdSeq, attachFileSeq) {
    let downForm = document.fileDownForm;
    downForm.prtDepoId.value = prtDepoId;
    downForm.prtDepoIdSeq.value = prtDepoIdSeq;
    downForm.fileSeq.value = attachFileSeq;

    downForm.action = '/listInvstg/lplAttach.do';
    downForm.method.value = 'downloadPrtdepoFile';

    downForm.submit();
}

// 의무보유내역 선택
// 팝업창으로부터 받은 정보를 각 form에 update (YSH, 2009/05/26)
scwin.setPrtDepoInfo = function (nm, id, shrs, objKind) {
    if ('' !== id) {
        scwin.prtDepoId = id;
    } else {
        $c.win.alert($c.data.getMessage("com_empty_0015"));
        return;
    }

    if ('' !== nm) {
        ibx_shrhdNm.setValue(nm);
    } else {
        $c.win.alert($c.data.getMessage("com_empty_0016"));
    }

    if ('' !== shrs) {
        ibx_fstPrtDepoShrs.setValue(shrs);
    } else {
        $c.win.alert($c.data.getMessage("com_empty_0017"));
    }
    ibx_objKind.setValue(objKind);
}

// 예비심사 접수 법인 목록
// 팝업창으로부터 받은 정보를 각 form에 update (YSH, 2009/05/26)
scwin.setCorpInfo = function (isurCd, comNm, bzProcsNo) {
    if (!$c.util.isEmpty(isurCd) && isurCd.length === 5) {
        ibx_isurCd.setValue(isurCd);
    } else {
        $c.win.alert($c.data.getMessage("com_empty_0009"));
        return;
    }

    if (!$c.util.isEmpty(comNm)) {
        ibx_comNm.setValue(comNm); // 회사명
    } else {
        $c.win.alert($c.data.getMessage("com_empty_0010"));
    }

    if (!$c.util.isEmpty(bzProcsNo)) {
        scwin.bzProcsNo = bzProcsNo; // 예비심사 업무처리번호
    }
}

/**
 * @method
 * @name scwin.checkValue
 * @author Inswave
 * @date 2026. 08. 28
 * @description 저장 전 입력값을 검증한다. 첫 번째 오류에서 멈추고 그 항목에 포커스를 준다.
 * @param
 * @returns
 * @hidden N
*/
scwin.checkValue = async function () {

    const options = {
        validateType: "alert",
        checkType: "single",
        focus: true,
        fields: {
            ibx_isurCd: { required: true, name: "회사명" },
            ibx_shrhdNm: { required: true, name: "의무보유자명" },
            ibx_fstPrtDepoShrs: { required: true, name: "최초의무보유 주식수" },
            ibx_objKind: { required: true, name: "의무보유대상종류" },
            ibx_prtDepoWithdShrs: { required: true, name: "처분주식수" },
            ibx_prtdepoWithdRsn: { required: true, name: "처분 사유" },
            ibx_lstPrtDepoShrs: { required: true, name: "최종의무보유주식수" },
        }
    };
    if (!await $c.validate.validateDataCollect(grp_form, options)) {
        return false;
    }

    if (cbx_prtDepoReopnYn.getSelectedIndex() === "0") { // check상태 - "0":true, "":false
        dma_saveReq.set("prtdepoReopnYn", "Y");
        if (cal_prtDepoReopnDD.getValue() === "") {
            await $c.win.alert($c.data.getMessage("com_req_input", "재의무보유일"));
            cal_prtDepoReopnDD.focus();
            return false;
        }

        if (cal_prtDepoReopnDD.getValue().length !== 8) {
            await $c.win.alert($c.data.getMessage("com_date_compare_0240", "재의무보유일"));
            cal_prtDepoReopnDD.focus();
            return false;
        }
    } else {
        dma_saveReq.set("prtdepoReopnYn", "N");
    }
    return true;

}

// insert
scwin.insertPrtDepoWithd = async function () {

    if (await scwin.checkValue() === false) {
        return;
    }

    if (ibx_upload1.getValue() === "") {
        $c.win.alert($c.data.getMessage("com_req_select", "처분신청 공문 관련 파일"));
        return;
    }
    if (ibx_upload2.getValue() === "") {
        $c.win.alert($c.data.getMessage("com_req_select", "첨부서류"));
        return;
    }

    if (await $c.win.confirm($c.data.getMessage("com_crud_0198", "저장"))) {
        muc.changeAction("/api/listing/listinvstg/prtdepo-disposal/create"); // action 설정
        muc.setParam(0, "prtdepoId", scwin.prtDepoId);	// 의무보유회사ID
        muc.setParam(1, "shrhdNm", dma_saveReq.get("shrhdNm")); // 의무보유자명
        // muc.setParam(2, "fstPrtdepoShrs", Number(dma_saveReq.get("fstPrtdepoShrs").replace(",", ""))); // 최초의무보유 주식수
        // muc.setParam(3, "prtdepoWithdShrs", Number(dma_saveReq.get("prtdepoWithdShrs").replace(",", ""))); // 처분 주식수
        muc.setParam(2, "fstPrtdepoShrs", Number(scwin.toNumber(dma_saveReq.get("fstPrtdepoShrs")))); // 최초의무보유 주식수
        muc.setParam(3, "prtdepoWithdShrs", Number(scwin.toNumber(dma_saveReq.get("prtdepoWithdShrs")))); // 처분 주식수
        // ibx_objKind 의무보유대상종류
        muc.setParam(4, "prtdepoWithdRsn", dma_saveReq.get("prtdepoWithdRsn")); // 처분 사유
        muc.setParam(5, "step1AttachIstmSubmitYn", dma_saveReq.get("step1AttachIstmSubmitYn")); // 1단계첨부서류제출여부
        muc.setParam(6, "step2AttachIstmSubmitYn", dma_saveReq.get("step2AttachIstmSubmitYn")); // 2단계첨부서류제출여부
        muc.setParam(7, "lstApprovYn", dma_saveReq.get("lstApprovYn")); // 상장처리상태코드
        // muc.setParam(8, "lstPrtdepoShrs", Number(dma_saveReq.get("lstPrtdepoShrs").replace(",", ""))); // 최종의무보유주식수
        muc.setParam(8, "lstPrtdepoShrs", Number(scwin.toNumber(dma_saveReq.get("lstPrtdepoShrs")))); // 최종의무보유주식수
        muc.setParam(9, "prtdepoReopnDd", dma_saveReq.get("prtdepoReopnDd"));	// 의무보유재개일자
        muc.setParam(10, "prtdepoReopnYn", dma_saveReq.get("prtdepoReopnYn")); // 의무보유재개여부 (체크박스)
        muc.setParam(11, "regId", $c.session.getUserInfo("integUsrId")); // 등록자ID

        muc.startUpload();
    }
}

// update
scwin.updatePrtDepoWithd = async function (updateType) {
    scwin.searchType = updateType;

    if (await scwin.checkValue() === false) {
        return;
    }

    if (await $c.win.confirm($c.data.getMessage("com_crud_0198", "수정"))) {

        muc.changeAction("api/listing/listinvstg/prtdepo-disposal/modify"); // action 설정
        muc.setParam(0, "prtdepoId", scwin.prtDepoId);	// 의무보유회사ID
        muc.setParam(1, "shrhdNm", dma_saveReq.get("shrhdNm")); // 의무보유자명
        muc.setParam(2, "fstPrtdepoShrs", dma_saveReq.get("fstPrtdepoShrs")); // 최초의무보유 주식수
        muc.setParam(3, "prtdepoWithdShrs", dma_saveReq.get("prtdepoWithdShrs")); // 처분 주식수
        // ibx_objKind 의무보유대상종류
        muc.setParam(4, "prtdepoWithdRsn", dma_saveReq.get("prtdepoWithdRsn")); // 처분 사유
        muc.setParam(5, "step1AttachIstmSubmitYn", dma_saveReq.get("step1AttachIstmSubmitYn")); // 1단계첨부서류제출여부
        muc.setParam(6, "step2AttachIstmSubmitYn", dma_saveReq.get("step2AttachIstmSubmitYn")); // 2단계첨부서류제출여부
        muc.setParam(7, "lstApprovYn", dma_saveReq.get("lstApprovYn")); // 상장처리상태코드
        muc.setParam(8, "lstPrtdepoShrs", dma_saveReq.get("lstPrtdepoShrs")); // 최종의무보유주식수
        muc.setParam(9, "prtdepoReopnDd", dma_saveReq.get("prtdepoReopnDd"));	// 의무보유재개일자
        muc.setParam(10, "prtdepoReopnYn", dma_saveReq.get("prtdepoReopnYn")); // 의무보유재개여부 (체크박스)
        muc.setParam(11, "regId", $c.session.getUserInfo("integUsrId")); // 등록자ID
        muc.setParam(12, "searchType", scwin.searchType); // 검색구분
        muc.setParam(13, "bzProcsNo", scwin.bzProcsNo); // 업무처리일련번호
        muc.setParam(14, "prtdepoNo", scwin.prtDepoNo); // 의무보유내역 일련번호?
        muc.setParam(15, "prtdepoWithdApplSeq", dma_saveReq.get("prtdepoWithdApplSeq")); // 의무보유신청일련번호

        // 2row 씩 파일의 데이터가 필요함 (처분신청 공문, 첨부서류)
        let attachFileSeqList = [];
        let prtdepoWithdAttachTpCdList = [];
        for (let i = 0; i < dlt_selectOneRes_prtDepoAttachFiles.getRowCount(); i++) {
            attachFileSeqList.push(dlt_selectOneRes_prtDepoAttachFiles.getCellData(i, "attachFileSeqList"));
            prtdepoWithdAttachTpCdList.push(dlt_selectOneRes_prtDepoAttachFiles.getCellData(i, "prtdepoWithdAttachTpCdList"));
        }
        muc.setParam(15, "attachFileSeq", attachFileSeqList); // 파일시퀸스
        muc.setParam(16, "prtdepoWithdAttachTpCd", prtdepoWithdAttachTpCdList); // 의무보유첨부구분코드
        muc.startUpload();
    }
}

scwin.fileUploadOndone = function () {
};

/* 
 * string, number 타입 모두 comma 처리
 */
scwin.setStringToNum = function (value) {
    return String(value).replace(/\B(?=(\d{3})(?!\d))/g, ",");
}

/**
 * @method
 * @name scwin.toNumber
 * @author Inswave
 * @date 2026. 08. 28
 * @description 천단위 콤마가 섞인 문자열을 숫자로 바꾼다. 값이 없으면 0 을 반환한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.toNumber = function (value) {
    if ($c.util.isEmpty(value)) return 0;

    return $c.num.unFormatNumber(value);
};
